var API_ENDPOINT = "http://100.93.89.102";
var API_PORT = "8009";

flow.set("API_endpoint", `${API_ENDPOINT}:${API_PORT}`);
flow.set("API_host", API_ENDPOINT);
flow.set("API_port", API_PORT);

node.status({fill:"green", shape:"dot", text:`${API_ENDPOINT}:${API_PORT}`});
node.warn(`Things MCP API configured: ${API_ENDPOINT}:${API_PORT}`);

return msg;

const endpoint = flow.get("API_endpoint");
const timestamp = new Date().toISOString();

msg.url = `${endpoint}/mcp`;

// Preserve original headers but ensure MCP-required ones
msg.headers = msg.headers || {};
msg.headers["Accept"] = "application/json, text/event-stream";
msg.headers["Content-Type"] = "application/json";

// Forward mcp-session-id header from incoming request to upstream
if (msg.req && msg.req.headers) {
    const sessionId = msg.req.headers["mcp-session-id"] || msg.req.headers["MCP-Session-ID"];
    if (sessionId) {
        msg.headers["mcp-session-id"] = sessionId;
    }
}

// Debug info
msg._debug = {
    timestamp: timestamp,
    transport: "streamable-http",
    targetUrl: msg.url,
    method: msg.req ? msg.req.method : "POST",
    originalHeaders: Object.keys(msg.headers)
};

node.status({fill:"blue", shape:"dot", text:`${timestamp.slice(11,19)} -> /mcp`});

return msg;

const timestamp = new Date().toISOString();

// Check for errors
if (msg.statusCode >= 400) {
    node.status({fill:"red", shape:"ring", text:`${timestamp.slice(11,19)} ERR ${msg.statusCode}`});
    node.error(`MCP Error ${msg.statusCode}: ${msg.payload}`, msg);
} else {
    node.status({fill:"green", shape:"dot", text:`${timestamp.slice(11,19)} OK ${msg.statusCode}`});
}

// Forward response headers (especially mcp-session-id) back to client
// In Node-RED, http request node puts response headers in msg.headers
// We need to preserve these for the http response node
const responseHeaders = msg.headers || {};

// Create headers object for response (http response node uses msg.headers)
msg.headers = {};

// Forward mcp-session-id header (case-insensitive)
for (const [key, value] of Object.entries(responseHeaders)) {
    const lowerKey = key.toLowerCase();
    if (lowerKey === "mcp-session-id") {
        msg.headers["mcp-session-id"] = value;
    }
    // Also forward content-type and other important headers
    if (["content-type", "content-length", "cache-control", "content-encoding"].includes(lowerKey)) {
        msg.headers[key] = value;
    }
}

// Add debug info
msg._debug = msg._debug || {};
msg._debug.responseTimestamp = timestamp;
msg._debug.statusCode = msg.statusCode;
msg._debug.responseSize = msg.payload ? msg.payload.length : 0;
msg._debug.responseHeaders = Object.keys(msg.headers);
msg._debug.sessionIdForwarded = !!msg.headers["mcp-session-id"];

return msg;

